// Access n8n's internal workflow memory
const memory = $getWorkflowStaticData('global');

// Create the memory array if this is the very first time running
memory.processedLinksSheet = memory.processedLinksSheet || [];

const out = [];

// Loop through all the scraped offers from the HTML1 node
for (const item of $input.all()) {
  const offerLink = item.json.Link;
  let imageURL = item.json.ImageURL || '';

  // Convert relative URLs to absolute URLs
  if (offerLink && !offerLink.startsWith('http')) {
    item.json.Link = 'https://alinma.com' + offerLink;
  }

  if (imageURL && !imageURL.startsWith('http')) {
    item.json.ImageURL = 'https://alinma.com' + imageURL;
  }

  // ONLYDEALS CHANGE: tag isNew instead of dropping seen links — the feed needs
  // the FULL offer set on every run. Memory tracking is preserved, so anything
  // listening for isNew === true still gets "what's new since last scrape".
  item.json.isNew = !memory.processedLinksSheet.includes(offerLink);
  if (item.json.isNew) {
    memory.processedLinksSheet.push(offerLink);
  }
  out.push(item);
}

return out;

// Get all items from the Deduplication node to recover URLs
// IMPORTANT: Ensure 'Code in JavaScript' matches the exact name of your Deduplication node
const dedupItems = $('Code in JavaScript').all();

// Helper function to parse various date formats
function parseDate(dateStr) {
  if (!dateStr) return null;
  dateStr = dateStr.trim();

  // Handle truncated years like "20..." -> assume 2026 or 2027
  if (dateStr.match(/\d{2}\.\.\.$/)) {
    dateStr = dateStr.replace(/\d{2}\.\.\.$/, '2026');
  }

  // Handle "Dec 31, 2026" format
  if (dateStr.match(/^[A-Za-z]{3}\s+\d{1,2},?\s+\d{4}$/)) {
    const parsed = new Date(dateStr);
    if (!isNaN(parsed.getTime())) return parsed.toISOString().split('T')[0];
  }

  // Handle "29 June 2026" format
  if (dateStr.match(/^\d{1,2}\s+[A-Za-z]+\s+\d{4}$/)) {
    const parsed = new Date(dateStr);
    if (!isNaN(parsed.getTime())) return parsed.toISOString().split('T')[0];
  }

  // Handle "June 17" format (no year - assume 2026)
  if (dateStr.match(/^[A-Za-z]+\s+\d{1,2}$/)) {
    const parsed = new Date(dateStr + ', 2026');
    if (!isNaN(parsed.getTime())) return parsed.toISOString().split('T')[0];
  }

  // Handle "25 June" format (no year - assume 2026)
  if (dateStr.match(/^\d{1,2}\s+[A-Za-z]+$/)) {
    const parsed = new Date(dateStr + ', 2026');
    if (!isNaN(parsed.getTime())) return parsed.toISOString().split('T')[0];
  }

  // Handle "31 July 20..." (truncated year)
  if (dateStr.match(/^\d{1,2}\s+[A-Za-z]+\s+\d{2}\.\.\.$/)) {
    const fixed = dateStr.replace(/\d{2}\.\.\.$/, '2026');
    const parsed = new Date(fixed);
    if (!isNaN(parsed.getTime())) return parsed.toISOString().split('T')[0];
  }

  return null;
}

const offers = $input.all().map((item, index) => {
  const data = item.json;

  // 1. Recover URLs from the Deduplication node
  let link = data.Link || data.terms_url || '';
  let imageURL = data.ImageURL || data.image_url || '';

  if (dedupItems[index] && dedupItems[index].json) {
    link = dedupItems[index].json.Link || link;
    imageURL = dedupItems[index].json.ImageURL || imageURL;
  }

  // 2. Combine all text sources for extraction
  const fullText = (data.description || '') + ' ' + (data.Offer || '') + ' ' + (data.offer_title || '');
  const termsText = data.TermsText || '';
  const allText = fullText + ' ' + termsText;

  let discountValue = '';
  let discountType = 'unknown';
  let maxDiscount = null;

  // 3. Extract Discount Value
  const percentMatch = fullText.match(/(\d+)%/);
  if (percentMatch) {
    discountValue = percentMatch[1] + '%';
    discountType = 'percentage';
  } else {
    const fixedMatch = fullText.match(/(?:SAR|SR)\s*(\d+)|(\d+)\s*(?:SAR|SR)/i);
    if (fixedMatch) {
      const amount = fixedMatch[1] || fixedMatch[2];
      discountValue = amount + ' SAR';
      discountType = 'fixed';
    }
  }

  // 4. Extract Max Discount
  const maxDiscMatch = allText.match(/(?:up to|capped at|maximum|max)\s+(?:SAR\s*)?(\d+(?:,\d{3})*)/i);
  if (maxDiscMatch) {
    maxDiscount = parseFloat(maxDiscMatch[1].replace(/,/g, ''));
  }

  // 5. Clean up Merchant ID
  let merchantRaw = data.Brand || data.offer_title || 'unknown';
  if (merchantRaw.toLowerCase().includes('cashback') ||
      merchantRaw.toLowerCase().includes('discount') ||
      merchantRaw.toLowerCase().includes('installment') ||
      merchantRaw.includes('$name')) {
     if (link) {
        const urlParts = link.split('/');
        const lastPart = urlParts[urlParts.length - 1];
        if (lastPart && lastPart.length > 2) {
            merchantRaw = lastPart.replace(/-/g, ' ').replace(/\d+/g, '').trim();
        }
     }
  }

  // 6. EXTRACT DATES FROM TERMS TEXT
  let startDate = null;
  let endDate = null;

  // Pattern 1: "from 29 June 2026 to 15 June 2027" (full format)
  const fullDateMatch = termsText.match(/(?:valid\s+from|from)\s+(\d{1,2}\s+[A-Za-z]+\s+\d{4})\s+(?:to|until)\s+(\d{1,2}\s+[A-Za-z]+\s+\d{4})/i);
  if (fullDateMatch) {
    startDate = parseDate(fullDateMatch[1]);
    endDate = parseDate(fullDateMatch[2]);
  }

  // Pattern 2: "from 25 June to 31 July 20..." (truncated year)
  if (!startDate || !endDate) {
    const shortDateMatch = termsText.match(/(?:valid\s+from|from)\s+(\d{1,2}\s+[A-Za-z]+)\s+(?:to|until)\s+(\d{1,2}\s+[A-Za-z]+\s+\d{2}(?:\.\.\.)?)/i);
    if (shortDateMatch) {
      startDate = parseDate(shortDateMatch[1]);
      endDate = parseDate(shortDateMatch[2]);
    }
  }

  // Pattern 3: "from June 17 to Dec 31, 20..." (month-first format)
  if (!startDate || !endDate) {
    const monthFirstMatch = termsText.match(/(?:valid\s+from|from)\s+([A-Za-z]+\s+\d{1,2})\s+(?:to|until)\s+([A-Za-z]+\s+\d{1,2},?\s+\d{2,4}(?:\.\.\.)?)/i);
    if (monthFirstMatch) {
      startDate = parseDate(monthFirstMatch[1]);
      endDate = parseDate(monthFirstMatch[2]);
    }
  }

  // Pattern 4: Single date "valid until 31 July 2026" or "expires 31/07/2026"
  if (!endDate) {
    const singleDateMatch = termsText.match(/(?:valid\s+(?:until|till)|expires?|ends?|end\s+date)[:\s]+(\d{1,2}\s+[A-Za-z]+\s+\d{2,4}(?:\.\.\.)?|\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/i);
    if (singleDateMatch) {
      endDate = parseDate(singleDateMatch[1]);
    }
  }

  return {
    json: {
      merchant_id: merchantRaw.toLowerCase().trim().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' '),
      source: 'alinma',
      source_type: 'bank',
      card_name: 'Alinma Card',
      offer_title: data.Brand || data.offer_title || 'Alinma Offer',
      description: data.description || data.Offer || '',
      discount_value: discountValue,
      discount_type: discountType,
      min_spend: null,
      max_discount: maxDiscount,
      start_date: startDate,
      end_date: endDate,
      terms_url: link,
      image_url: imageURL,
      active: 1,
      scraped_at: new Date().toISOString()
    }
  };
});

return offers;

// ONLYDEALS OUTPUT STAGE
// Normalized Alinma rows → offer.v1 payload for the ingest endpoint.
const rows = $input.all().map(i => i.json);
const now = new Date();

function guessCategory(text) {
  const t = (text || '').toLowerCase();
  if (/coffee|caf\u00e9/.test(t)) return 'coffee';
  if (/restaurant|dining|food|burger|chicken/.test(t)) return 'dining';
  if (/hotel|rotana|stay/.test(t)) return 'hotels';
  if (/fly|flight|travel|emirates/.test(t)) return 'travel';
  if (/fashion|style|namshi|clothes/.test(t)) return 'fashion';
  if (/electr|jarir|extra|phone/.test(t)) return 'electronics';
  if (/grocer|danube|tamimi/.test(t)) return 'groceries';
  if (/fuel|petrol|petromin/.test(t)) return 'fuel';
  if (/cinema|movie|vox/.test(t)) return 'entertainment';
  return 'online';
}

const offers = rows.map((r, i) => {
  const pct = (r.discount_value || '').match(/(\d+(?:\.\d+)?)\s*%/);
  const fixed = (r.discount_value || '').match(/(\d+(?:,\d{3})*)\s*(?:SAR|SR)/i);

  let discountLabel = 'OFFER';
  let value = 0;
  let kind = 'percent';
  if (pct) {
    discountLabel = '\u2212' + pct[1] + '%';
    value = parseFloat(pct[1]);
  } else if (fixed) {
    discountLabel = '\u2212' + fixed[1].replace(/,/g, '') + ' SR';
    kind = 'cashback';
  }

  const merchant = (r.offer_title || 'Alinma offer').trim();
  const terms = ['Scraped from alinma.com media campaigns by onlydeals-alinma \u2014 open the link for full terms.'];
  if (r.max_discount) terms.push('Maximum discount SAR ' + r.max_discount + '.');
  if (r.start_date && r.end_date) terms.push('Valid ' + r.start_date + ' \u2192 ' + r.end_date + '.');

  return {
    id: 'alinma-' + String(r.merchant_id || i).replace(/\s+/g, '-').slice(0, 40) + '-' + i,
    merchant: merchant,
    headline: (r.description || merchant + ' offer for Alinma card holders').trim(),
    discountLabel: discountLabel,
    value: value,
    kind: kind,
    category: guessCategory(merchant + ' ' + r.description),
    bank: 'Alinma Bank',
    card: r.card_name || 'Alinma Card',
    image: r.image_url || '',
    cards: [r.card_name || 'Alinma credit cards'],
    link: r.terms_url || 'https://alinma.com/en/Media-Campaigns/Stores',
    expiresAt: r.end_date ? r.end_date + 'T12:00:00.000Z' : null,
    terms: terms
  };
});

const payload = {
  version: 'offer.v1',
  generatedAt: now.toISOString(),
  generator: 'n8n:onlydeals-alinma',
  sources: [{
    id: 'alinma',
    name: 'Alinma Bank',
    status: offers.length ? 'live' : 'error',
    count: offers.length,
    note: offers.length + ' offers \u00b7 detail-page scrape \u00b7 ' + rows.length + ' campaigns normalized',
    at: now.getTime()
  }],
  offers: offers
};

return [{ json: { payload, count: offers.length } }];

const p = $('Build offer.v1 payload').first().json.payload;
const s = (p.sources && p.sources[0]) || {};
return [{ json: { timestamp: p.generatedAt, source: s.id || '', offers: s.count || 0, status: s.status || '', generator: p.generator } }];
